package com.example.com.englishai.backend.presentation.rest.admin;
import com.example.com.englishai.backend.infrastructure.persistence.repository.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/dashboard") public class AdminDashboardController { private final UserJpaRepository users; private final ConversationJpaRepository conversations; private final PredefinedAvatarJpaRepository avatars; private final ScenarioDefinitionJpaRepository scenarios; public AdminDashboardController(UserJpaRepository u,ConversationJpaRepository c,PredefinedAvatarJpaRepository a,ScenarioDefinitionJpaRepository s){users=u;conversations=c;avatars=a;scenarios=s;} @GetMapping public Dashboard get(){return new Dashboard(users.count(),conversations.count(),avatars.count(),scenarios.count(),scenarios.countByEnabledTrue());} public record Dashboard(long users,long conversations,long avatars,long scenarios,long activeScenarios){} }
